package org.sleepwell.app;
import org.junit.Test;import static org.junit.Assert.*;
/** Actual timer policy and durable fake-port delivery; no Android output. */
public final class PowerNapTest {
 @Test public void minimumThenLaterIntervalPreserveExactLatestDeadline(){NapEngineTest f=new NapEngineTest();NapPlan p=NapPlan.createPower(f.clock,20,60,0,false);f.engine.arm(1,p);assertTrue(p.power());assertEquals(80,p.minutes);assertEquals(20,p.minimumRestMinutes);assertEquals(60,p.wakeInterval());assertEquals(4800000,f.delay);assertEquals(f.clock.wall+4800000,p.deadlineWall());f.clock.advance(1199999);assertFalse(p.smartReady(f.clock,60,1,3,100));f.engine.receive(1,p.nonce,true);assertEquals(0,f.fires);f.clock.advance(1);assertTrue(p.smartReady(f.clock,60,.12,2,20));f.engine.receive(1,p.nonce,true);assertEquals(1,f.fires);assertFalse(f.row.enabled);f.engine.receive(1,p.nonce,true);assertEquals(1,f.fires);}
 @Test public void noMotionStillDeliversOnceAtHardLatest(){NapEngineTest f=new NapEngineTest();NapPlan p=NapPlan.createPower(f.clock,20,15,0,true);f.engine.arm(1,p);f.clock.advance(2099999);f.engine.receive(1,p.nonce,false);assertEquals(0,f.fires);assertEquals(1,f.delay);f.clock.advance(1);f.engine.receive(1,p.nonce,false);f.engine.receive(1,p.nonce,false);assertEquals(1,f.fires);assertEquals(20,f.row.plan.minimumRestMinutes);}
 @Test public void wallShiftCannotShortenMinimumOrExtendLatestWithinBoot(){NapEngineTest f=new NapEngineTest();NapPlan p=NapPlan.createPower(f.clock,20,15,0,false);f.clock.wall+=86400000;assertEquals(1200000,p.minimumRemaining(f.clock));assertEquals(2100000,p.remaining(f.clock));assertFalse(p.smartInterval(f.clock));f.clock.advance(1200000);assertTrue(p.smartInterval(f.clock));assertEquals(900000,p.remaining(f.clock));}
 @Test public void scheduledStartProtectsMinimumAfterActualFutureStart(){NapEngineTest f=new NapEngineTest();NapPlan p=NapPlan.createPower(f.clock,20,15,3600000,false);f.engine.arm(1,p);assertEquals(5700000,f.delay);f.clock.advance(3600000);assertFalse(p.smartInterval(f.clock));f.clock.advance(1199999);assertFalse(p.smartInterval(f.clock));f.clock.advance(1);assertTrue(p.smartInterval(f.clock));}
 @Test public void bootFallbackRetainsOriginalBoundaries(){NapEngineTest f=new NapEngineTest();NapPlan p=NapPlan.createPower(f.clock,20,15,0,false);f.clock.advance(600000);f.clock.boot++;f.clock.elapsed=1;assertEquals(600000,p.minimumRemaining(f.clock));assertEquals(1500000,p.remaining(f.clock));f.clock.advance(600000);assertTrue(p.smartInterval(f.clock));}
 @Test public void cancelReplacementAndImportedInactivePlansCannotSmartClaim(){NapEngineTest f=new NapEngineTest();NapPlan old=NapPlan.createPower(f.clock,20,15,0,false);f.engine.arm(1,old);f.engine.cancel(1,old.nonce);f.clock.advance(1200000);f.engine.receive(1,old.nonce,true);assertEquals(0,f.fires);NapPlan fresh=NapPlan.createPower(f.clock,10,5,0,false);f.engine.arm(1,fresh);f.engine.receive(1,old.nonce,true);assertEquals(0,f.fires);assertEquals(fresh.nonce,f.row.plan.nonce);assertEquals(10,f.row.plan.minimumRestMinutes);}
 @Test public void actualSignalGateStillRejectsMissingInvalidOrInsufficientMotion(){NapEngineTest f=new NapEngineTest();NapPlan p=NapPlan.createPower(f.clock,20,15,0,false);f.clock.advance(1200000);assertFalse(p.smartReady(f.clock,0,.5,2,30));assertFalse(p.smartReady(f.clock,15,Double.NaN,2,30));assertFalse(p.smartReady(f.clock,15,.1,2,30));assertFalse(p.smartReady(f.clock,15,.5,1,30));assertFalse(p.smartReady(f.clock,15,.5,2,19));assertTrue(p.smartReady(f.clock,15,.5,2,30));f.clock.advance(900000);assertFalse(p.smartReady(f.clock,15,.5,2,30));}
 @Test public void boundedIntervalsAndLegacyStateRemainExplicit(){NapEngineTest f=new NapEngineTest();NapPlan old=NapPlan.create(f.clock,20,0,true);assertFalse(old.power());assertEquals(0,old.minimumRestMinutes);assertEquals(0,old.state(NapPlan.Phase.CANCELLED,"").minimumRestMinutes);for(int[] pair:new int[][]{{0,15},{20,0},{20,61},{600,1}})assertThrows(IllegalArgumentException.class,()->NapPlan.createPower(f.clock,pair[0],pair[1],0,false));assertThrows(ArithmeticException.class,()->NapPlan.createPower(f.clock,Integer.MAX_VALUE,1,0,false));}
}
